            if status != 'scheduled' or host_user_id != current_user_id:
                continue
            start_utc = parse_utc_dt(start_time_utc_str)
            created_utc = parse_utc_dt(sess_created_at_str)
            if start_utc is None or created_utc is None:
                continue
            expected_start_utc = compute_next_friday_2030_utc(created_utc, current_user_tz)
            if expected_start_utc is None:
                continue
            # Compare to the second
            if int(start_utc.timestamp()) == int(expected_start_utc.timestamp()):
                session_ok = True
                break
        if session_ok:
            valid_room_candidates.append(room_id)

    # There must be exactly one unambiguous room that satisfies all criteria
    if len(valid_room_candidates) == 1:
        return {"result": "complete"}

    return {"result": "others"}

