    user_query = """
        SELECT cs.user_id 
        FROM channel_subscriptions cs
        JOIN channels c ON cs.channel_id = c.id
        WHERE c.title = 'Indie Fridays Live'
        AND cs.status = 'active'
        AND cs.start_at <= '2026-01-31 23:59:59'
        AND (cs.end_at IS NULL OR cs.end_at >= '2026-01-01 00:00:00')
    """
    user_results = safe_query(final_db_path, user_query)
    if not user_results:
        return {"result": "others"}

    user_id = user_results[0][0]
    if user_id != 2:
        return {"result": "others"}

    # Step 2: Get valid passes for this user in Jan 2026
    passes_query = """
        SELECT ap.id, ap.event_id, ap.access_type, ap.status
        FROM access_passes ap
        JOIN events e ON ap.event_id = e.id
        WHERE ap.user_id = ?
        AND e.start_time >= '2026-01-01 00:00:00'
        AND e.start_time <= '2026-01-31 23:59:59'
        AND ap.status IN ('active', 'scheduled')
        ORDER BY ap.event_id
