        if obj is not None:
            mp = build_map_from_obj(obj)
            if mp:
                return mp

        # Regex fallback: detect event groups and pass IDs by textual patterns
        # Find occurrences of event id mentions
        ev_iter = list(re.finditer(r"(?i)\b(event[_\s]*id|event)\b[^0-9]{0,3}(\d+)\b", s))
        if not ev_iter:
            return None
        # Build segments per event occurrence
        positions = [(m.start(), int(m.group(2))) for m in ev_iter]
        positions.sort()
        segments = []
        for i, (start, eid) in enumerate(positions):
            end = positions[i+1][0] if i+1 < len(positions) else len(s)
            segments.append((eid, s[start:end]))
        mapping: dict[int, set[int]] = {}
        for eid, seg in segments:
            # Capture patterns like 'pass id: N', 'access pass id N', 'pass #N'
            ids = set()
            for rx in [
                r"(?i)\b(?:pass|access(?:\s*pass)?)\b[^0-9]{0,10}\bid\b[^0-9]{0,3}(\d+)\b",
                r"(?i)\b(?:pass|access(?:\s*pass)?)\s*#\s*(\d+)\b",
                r"(?i)\b(?:pass|access(?:\s*pass)?)\b[^\n]{0,40}\b(id|pass_id)\b[^0-9]{0,3}(\d+)\b",
            ]:
                for m in re.finditer(rx, seg):
                    # If regex has two groups (like (id|pass_id) and (\d+)), last group is the number
                    num = m.group(m.lastindex)
                    if isinstance(num, str) and num.isdigit():
                        ids.add(int(num))
            if ids:
                mapping[eid] = ids
        return mapping if mapping else None

    # 1) Identify channel id for 'Indie Fridays Live'
    ch_rows = safe_query(final_db_path, "SELECT id FROM channels WHERE title = ?", ("Indie Fridays Live",))
    if len(ch_rows) != 1:
        return {"result": "others"}
    channel_id = ch_rows[0][0]

    # 2) Determine the unique viewer with an active subscription covering the entire window
    window_start = "2026-01-01 00:00:00"
    window_end = "2026-01-31 23:59:59"
    subs_rows = safe_query(
        final_db_path,
        """
        SELECT user_id FROM channel_subscriptions
        WHERE channel_id = ? AND status = 'active'
          AND start_at <= ? AND (end_at IS NULL OR end_at >= ?)
        GROUP BY user_id
        """,
        (channel_id, window_start, window_end)
    )
    if len(subs_rows) != 1:
        # Ambiguous which viewer; cannot be 100% certain
        return {"result": "others"}
    viewer_user_id = subs_rows[0][0]

    # 3) Get events in date window (any channel, per task wording)
    ev_rows = safe_query(
        final_db_path,
        "SELECT id, start_time, end_time FROM events WHERE start_time BETWEEN ? AND ? ORDER BY id",
        (window_start, window_end)
    )
    if not ev_rows:
        return {"result": "others"}
    event_ids_in_window = [r[0] for r in ev_rows]

    # 4) Compute expected valid passes for this viewer overlapping each event time and with valid statuses
    ap_rows = safe_query(
        final_db_path,
        """
        SELECT ap.id, ap.event_id, ap.access_type, ap.status, ap.valid_from, ap.valid_until
        FROM access_passes ap
        JOIN events e ON e.id = ap.event_id
        WHERE ap.user_id = ?
          AND e.start_time BETWEEN ? AND ?
          AND ap.status IN ('active','scheduled')
          AND ap.valid_until >= e.start_time
          AND ap.valid_from <= e.end_time
        ORDER BY ap.event_id, ap.id
        """,
        (viewer_user_id, window_start, window_end)
    )
    if not ap_rows:
        return {"result": "others"}

    expected_map: dict[int, set[int]] = {}
    for pid, eid, atype, status, vf, vu in ap_rows:
        expected_map.setdefault(eid, set()).add(int(pid))

    # We expect at least some passes; otherwise cannot verify
    if not expected_map:
        return {"result": "others"}

    # 5) Parse final_answer and validate grouping and pass IDs
    if not isinstance(final_answer, str) or not final_answer.strip():
        return {"result": "others"}

    parsed_map = parse_event_pass_map(final_answer)
    if not parsed_map:
        return {"result": "others"}

    # Only consider event IDs that are in the date window (ignore any other mentions)
    # Filter both maps to intersection with event_ids_in_window
    expected_keys = set(expected_map.keys())
    # Remove any entries for events with zero passes (should not exist in expected_map)
    parsed_filtered = {eid: set(pids) for eid, pids in parsed_map.items() if eid in event_ids_in_window}

    # Strict match: keys must match exactly, and pass-id sets must match exactly per event
    if set(parsed_filtered.keys()) != expected_keys:
        return {"result": "others"}
    for eid in expected_keys:
        exp_set = expected_map.get(eid, set())
        got_set = parsed_filtered.get(eid, set())
        if got_set != exp_set:
            return {"result": "others"}

    # Additional safety: ensure there are no extra event groups with IDs in window outside expected keys
    extra_in_answer = [eid for eid in parsed_map.keys() if (eid in event_ids_in_window and eid not in expected_keys)]
    if extra_in_answer:
        return {"result": "others"}

    return {"result": "complete"}
